"use client";

import { BrandCard } from "@/components/ui/cards/BrandCard";
import React, { useState } from "react";
import brandsData from "@/data/brandLogos";

// Import types from your features folder
import type { Brand, BrandCategory } from "@/features/brand/types/brand";

// Dynamically get all categories + "All"
const allCategories: (BrandCategory | "All")[] = [
  "All",
  "sneakers",
  "fashion",
  "sneakers",
  "watches",
  "accessories",
]; // Add all your actual categories here

export default function BrandsPage() {
  const [selectedCategory, setSelectedCategory] = useState<BrandCategory | "All">("All");
  const [sortOption, setSortOption] = useState<"a-z" | "z-a">("a-z");

  // Filter and sort
  const displayedBrands = brandsData
    .filter((b: Brand) =>
      selectedCategory === "All" ? true : b.categories?.includes(selectedCategory as BrandCategory)
    )
    .sort((a: Brand, b: Brand) =>
      sortOption === "a-z" ? a.name.localeCompare(b.name) : b.name.localeCompare(a.name)
    );

  return (
    <main className="min-h-screen bg-black text-white p-4 md:pt-24">
      {/* Header */}
      <header className="mb-6">
        <h1 className="text-4xl font-black uppercase italic tracking-tighter">
          All Brands
        </h1>
        <p className="text-white/40 text-sm mt-2">
          Explore our premium collection by manufacturer
        </p>
      </header>

      {/* Sticky filter/sort bar */}
      <div className="sticky top-14 flex w-full justify-between border-y items-center z-20 bg-black border-b border-white/50 py-2 mb-4">
        <select
          value={selectedCategory}
          onChange={(e) => setSelectedCategory(e.target.value as BrandCategory | "All")}
          className="w-full text-white px-3 py-2 outline-0"
        >
          {allCategories.map((cat) => (
            <option key={cat} value={cat}>
              {cat}
            </option>
          ))}
        </select>

        <select
          value={sortOption}
          onChange={(e) => setSortOption(e.target.value as "a-z" | "z-a")}
          className="w-full text-white px-3 py-2"
        >
          <option value="a-z">A - Z</option>
          <option value="z-a">Z - A</option>
        </select>
      </div>

      {/* Brands Grid */}
      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
        {displayedBrands.map((brand: Brand) => (
          <BrandCard key={brand.slug} brand={brand} />
        ))}
      </div>
    </main>
  );
}
